using EqlTracker.Core;
using System.Text.Json;

static class ProgressActionTests
{
    internal static void Register(Action<string,Action> register)
    {
        void Test(string name,Action run)=>register("Progress actions and sources · "+name,run);
        static void Check(bool value){if(!value)throw new Exception("Assertion failed");}
        var cat=Json.Read<Catalog>(Path.Combine(AppContext.BaseDirectory,"data/catalog.json"));
        Test("hilt coordinates unify wording and preserve original evidence",()=>{var item=cat.Find("Unjeweled Dragon Head Hilt")!;var before=JsonSerializer.Serialize(item);var route=ProgressPresentation.SourcesFor([item.Key],cat).Single();Check(route.Evidence.Count==2&&route.Additional.Count(s=>s.StartsWith("Coordinates:"))==1&&route.Additional.Contains("Under the aviak tower")&&!route.Additional.Any(s=>s.Contains("Pick Up")||s.Contains("checklist")));Check(before==JsonSerializer.Serialize(item));});
        Test("distinct ground-spawn coordinates stay separate",()=>{var item=EquipmentPositions.Copy(cat.Find("Unjeweled Dragon Head Hilt")!);item.Sources.Add(new(){Zone="Lake Rathetear",Method="Ground spawn",Coordinates="-10, 20",Mob="Near a different tower"});Check(ProgressPresentation.SourcesFor([item.Key],new(){Items=[item]}).Count==2);});
        Test("unqualified ground-spawn evidence does not create a duplicate box",()=>{var item=EquipmentPositions.Copy(cat.Find("Unjeweled Dragon Head Hilt")!);item.Sources.Add(new(){Zone="Lake Rathetear",Method="Drop",Mob="Ground Spawn",WikiUrl=item.WikiUrl});var route=ProgressPresentation.SourcesFor([item.Key],new(){Items=[item]}).Single();Check(route.Evidence.Count==3&&route.Method=="Ground spawn");});
        Test("unknown coordinates with different documented locations are separate",()=>{var item=new ItemDefinition{Key="a",Name="A",Sources=[new(){Zone="Zone",Method="Ground spawn",Mob="Under the tower"},new(){Zone="Zone",Method="Ground spawn",Mob="Near the river"}]};Check(ProgressPresentation.SourcesFor([item.Key],new(){Items=[item]}).Count==2);});
        Test("pickup prose is covered but extra conditions stay visible",()=>{var route=ProgressPresentation.SourcesFor(["unjeweled dragon head hilt"],cat).Single();Check(AcquisitionPresentation.CoversPickup("Pick Up Unjeweled Dragon Head Hilt (+2513, +920)",route));Check(!AcquisitionPresentation.CoversPickup("Pick Up Unjeweled Dragon Head Hilt (+2513, +920) at night",route));});
        Test("coordinate punctuation and signs normalize without changing values",()=>{Check(AcquisitionPresentation.Coordinates("(+2513, +920)")==AcquisitionPresentation.Coordinates("2513,920"));Check(AcquisitionPresentation.Coordinates("-2513,920")!=AcquisitionPresentation.Coordinates("2513,920"));});
        Test("NPC spelling typography and article duplicates keep evidence",()=>{var item=new ItemDefinition{Key="gem",Name="Gem",Sources=[new(){Zone="Chardok",Mob="a Di’Zok Cryptmaster"},new(){Zone="Chardok",Mob="A Di'Zok Cryptmaster"}]};var route=ProgressPresentation.SourcesFor([item.Key],new(){Items=[item]}).Single();Check(route.Evidence.Count==2);});
        Test("vendor aliases normalize while method differences remain",()=>{Check(AcquisitionPresentation.Method(new(){Method="Sold by"})=="Purchase");Check(AcquisitionPresentation.Method(new(){Method="Vendor"})=="Purchase");Check(AcquisitionPresentation.Method(new(){Method="Drop"})=="Drop");});
        Test("quantity and raid requirements are not discarded as repeated source text",()=>{var item=new ItemDefinition{Key="gem",Name="Gem",Sources=[new(){Zone="Zone",Mob="a keeper",Notes="Kill a keeper in Zone, loot Gem. Bring two friends; raid required."}]};Check(ProgressPresentation.SourcesFor([item.Key],new(){Items=[item]}).Single().Additional.Any(s=>s.Contains("two friends")));});
        Test("Lava Rock loot is stock even though Quest flag is not a relationship",()=>{var item=new ItemDefinition{Key="lava rock",Name="Lava Rock",Display=new(){Flags=["MAGIC ITEM","QUEST ITEM"]}};var inventory=new InventorySnapshot();var observation=new LogParser("ExampleHero").Parse("[Wed Oct 21 12:00:00 2026] You have looted a Lava Rock from a fire elemental's corpse.","log:100")!.Item!;InventoryParser.Apply(inventory,observation,"log:100");Check(inventory.Count(item)==1&&new ProgressBrowseIndex(new(){Items=[item]}).Choices(ProgressBrowseMode.Item,new(),inventory,false,"").Count==0);});
        Test("duplicate loot and destroy IDs remain idempotent after restart",()=>{var time=new DateTime(2026,10,21,12,0,0);var inventory=new InventorySnapshot();var loot=new ItemObservation(time,"Token","Looted",2,"a keeper");InventoryParser.Apply(inventory,loot,"log:100");InventoryParser.Apply(inventory,loot,"log:100");inventory=EquipmentPositions.Copy(inventory);InventoryParser.Apply(inventory,loot,"log:100");var destroy=new ItemObservation(time.AddSeconds(1),"Token","Destroyed",1,"");InventoryParser.Apply(inventory,destroy,"log:200");InventoryParser.Apply(inventory,destroy,"log:200");Check(inventory.Count(new(){Name="Token"})==1);});
        Test("explicit destroyed rank removes only that rank",()=>{var stock=new InventorySnapshot{Entries=[new(){Name="Sword +4",Count=1},new(){Name="Sword +5",Count=1}]};InventoryParser.Apply(stock,new(DateTime.Now,"Sword +5","Destroyed",1,""),"log:1");Check(stock.Entries[0].Count==1&&stock.Entries[1].Count==0);});
        Test("ambiguous rank removal retains uncertainty instead of choosing lowest rank",()=>{var stock=new InventorySnapshot{Entries=[new(){Name="Sword +4",Count=1},new(){Name="Sword +5",Count=1}]};InventoryParser.Apply(stock,new(DateTime.Now,"Sword","Destroyed",1,""),"log:1");Check(stock.Entries.All(e=>e.Count==1&&e.Estimated)&&stock.Warning.Contains("ambiguous"));});
        Test("collection presence is never destroyed as a physical copy",()=>{var stock=new InventorySnapshot{Entries=[new(){Name="Token",Count=null,Location="Collection"}]};InventoryParser.Apply(stock,new(DateTime.Now,"Token","Destroyed",1,""),"log:1");Check(stock.Entries.Single().Count==null&&stock.Warning.Contains("exceeds"));});
        Test("complete capture fence skips old observations and applies later ones once",()=>{var time=new DateTime(2026,10,21,12,0,0);var stock=new InventorySnapshot{CapturedAt=time,ExportLogId="g:200",Entries=[new(){Name="Token",Count=3}]};InventoryParser.Apply(stock,new(time,"Token","Looted",1,""),"g:100");InventoryParser.Apply(stock,new(time,"Token","Looted",1,""),"g:300");InventoryParser.Apply(stock,new(time,"Token","Looted",1,""),"g:300");Check(stock.Count(new(){Name="Token"})==4);});
        Test("autovendored new loot never subtracts a previously owned copy",()=>{var stock=new InventorySnapshot{Entries=[new(){Name="Token",Count=1}]};InventoryParser.Apply(stock,new(DateTime.Now,"Token","Sold",1,"a keeper"),"log:1");Check(stock.Count(new(){Name="Token"})==1);});
        Test("ownership tooltip distinguishes capture and subsequent log updates",()=>{var stock=new InventorySnapshot{CapturedAt=DateTime.Now.AddMinutes(-1)};InventoryParser.Apply(stock,new(DateTime.Now,"Token","Looted",1,"a keeper"),"log:1");var text=stock.Ownership(new(){Name="Token"});Check(text.Contains("Complete capture")&&text.Contains("Log updates through")&&text.Contains("placement remains unverified"));});
    }
}
